type Mode = "overview" | "structure" | "forms" | "tables" | "workflows" | "statuses" | "documents" | "notifications" | "numbering" | "roles" | "history" | "backup";
type ModalKind = "tab" | "section" | "field" | "table" | "workflow" | "status" | "document" | "notification" | "numbering" | "role" | null;
type ModalState = { kind: ModalKind; id?: string; parentId?: string };
type BuilderTab = { id: string; label: string; systemTarget?: string; visible: boolean; archived: boolean; order: number };
type BuilderSection = { id: string; tabId: string; title: string; description: string; type: "form" | "table" | "dashboard"; visible: boolean; archived: boolean; order: number };
type BuilderField = { id: string; sectionId: string; label: string; key: string; type: "text" | "number" | "date" | "datetime" | "textarea" | "select" | "checkbox"; required: boolean; visible: boolean; archived: boolean; order: number; options: string[]; placeholder?: string; helpText?: string; defaultValue?: string; readOnly?: boolean; unique?: boolean; showInTable?: boolean; searchable?: boolean; filterable?: boolean; sortable?: boolean; min?: number | null; max?: number | null; validationPattern?: string; visibilityRule?: string };
type BuilderAction = { id: string; tabId: string; label: string; type: string; visible: boolean; archived: boolean; order: number; confirmation: string };
type BuilderRole = { id: string; name: string; active: boolean; permissions: string[] };
type TableConfig = { id: string; sectionId: string; pagination: boolean; pageSize: number; search: boolean; filters: boolean; exportExcel: boolean; exportPdf: boolean; rowNumbers: boolean; bulkActions: boolean; stickyHeader: boolean; compact: boolean };
type WorkflowStage = { id: string; name: string; role: string; required: boolean; canReturn: boolean; canEdit: boolean; deadlineHours: number };
type Workflow = { id: string; name: string; entity: string; active: boolean; autoGeneratePdf: boolean; stages: WorkflowStage[] };
type StatusConfig = { id: string; entity: string; name: string; code: string; active: boolean; final: boolean; allowEdit: boolean; order: number };
type DocumentRule = { id: string; name: string; entity: string; trigger: string; templateName: string; output: "PDF" | "DOCX" | "PDF и DOCX"; mergePackage: boolean; active: boolean };
type NotificationRule = { id: string; name: string; event: string; channel: "В системе" | "Email" | "Telegram" | "В системе и Email"; recipient: string; message: string; active: boolean };
type NumberingRule = { id: string; entity: string; prefix: string; nextNumber: number; digits: number; reset: "Никогда" | "Ежегодно" | "Ежемесячно"; separator: string; active: boolean };
type AuditRow = { id: string; at: string; actor: string; action: string; entity: string; entityId: string; details: string };
type AdvancedConfig = { tables: TableConfig[]; workflows: Workflow[]; statuses: StatusConfig[]; documents: DocumentRule[]; notifications: NotificationRule[]; numbering: NumberingRule[] };
type StoredData = Record<string, unknown> & { builder?: { tabs?: BuilderTab[]; sections?: BuilderSection[]; fields?: BuilderField[]; actions?: BuilderAction[]; roles?: BuilderRole[]; records?: unknown[]; advanced?: AdvancedConfig }; audit?: AuditRow[] };

