function emptyData(): StoredData {
  return { builder: { tabs: [], sections: [], fields: [], actions: [], roles: [{ id: "role-admin", name: "Администратор", active: true, permissions: ["admin.full"] }], records: [], advanced: defaultAdvanced }, audit: [] };
}
function normalizeData(value: StoredData): StoredData {
  const base = emptyData();
  const builder = value.builder || {};
  return {
    ...base,
    ...value,
    builder: {
      ...base.builder,
      ...builder,
      tabs: builder.tabs || [],
      sections: builder.sections || [],
      fields: builder.fields || [],
      actions: builder.actions || [],
      roles: (builder.roles || []).map((role) => ({ ...role, permissions: normalizeLegacyPermissions(role.permissions || []) })),
      records: builder.records || [],
      advanced: { ...defaultAdvanced, ...(builder.advanced || {}) },
    },
    audit: value.audit || [],
  };
}
function normalizeLegacyPermissions(values: string[]) {
  const map: Record<string, string> = { view: "view.all", create: "data.create", edit: "data.edit", delete: "data.delete", approve: "request.approve", return: "request.return", configure: "admin.constructor", export: "data.export", send: "request.send", sign: "document.view", "view-own": "view.own" };
  return Array.from(new Set(values.map((value) => map[value] || value)));
}
function sorted<T extends { order: number }>(rows: T[]) { return [...rows].sort((a, b) => a.order - b.order); }
function s(value: FormDataEntryValue | null) { return String(value ?? "").trim(); }
function n(value: FormDataEntryValue | null) { return Number(String(value ?? "").replace(",", ".")) || 0; }

export default function AdvancedAdminWorkspace() {
  const [data, setData] = useState<StoredData>(() => emptyData());
  const [mode, setMode] = useState<Mode>("overview");
  const [modal, setModal] = useState<ModalState>({ kind: null });
  const [selectedTab, setSelectedTab] = useState("");
  const [selectedSection, setSelectedSection] = useState("");
  const [notice, setNotice] = useState("");
  const builder = data.builder!;
  const advanced = builder.advanced!;

  useEffect(() => {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      const normalized = normalizeData(raw ? JSON.parse(raw) as StoredData : emptyData());
      setData(normalized);
      setSelectedTab(normalized.builder?.tabs?.[0]?.id || "");
    } catch { setData(emptyData()); }
  }, []);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(""), 3200); return () => clearTimeout(timer); }, [notice]);

  const selectedTabRow = builder.tabs?.find((row) => row.id === selectedTab);
  const selectedSectionRow = builder.sections?.find((row) => row.id === selectedSection);
  const sectionsForTab = useMemo(() => sorted((builder.sections || []).filter((row) => row.tabId === selectedTab)), [builder.sections, selectedTab]);
  const fieldsForSection = useMemo(() => sorted((builder.fields || []).filter((row) => row.sectionId === selectedSection)), [builder.fields, selectedSection]);

  function persist(next: StoredData, action?: Omit<AuditRow, "id" | "at" | "actor">) {
    const audit = action ? [{ id: uid("audit"), at: new Date().toLocaleString("ru-RU"), actor: "Администратор", ...action }, ...(next.audit || [])].slice(0, 1000) : next.audit || [];
    const withAudit = { ...next, audit };
    setData(withAudit);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(withAudit));
    window.dispatchEvent(new StorageEvent("storage", { key: STORAGE_KEY, newValue: JSON.stringify(withAudit) }));
    setNotice("Изменения сохранены");
  }
  function updateBuilder(nextBuilder: StoredData["builder"], action: string, entity: string, entityId: string, details: string) {
    persist({ ...data, builder: nextBuilder }, { action, entity, entityId, details });
  }
  function exportData() { const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const anchor = document.createElement("a"); anchor.href = URL.createObjectURL(blob); anchor.download = `gazel-logistics-full-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); URL.revokeObjectURL(anchor.href); }
  function importData(file: File) { const reader = new FileReader(); reader.onload = () => { try { const next = normalizeData(JSON.parse(String(reader.result)) as StoredData); persist(next, { action: "Импорт", entity: "Система", entityId: "backup", details: "Загружена резервная копия" }); } catch { alert("Некорректный файл резервной копии"); } }; reader.readAsText(file); }
  function move<T extends { id: string; order: number }>(rows: T[], id: string, direction: -1 | 1) { const ordered = sorted(rows); const index = ordered.findIndex((row) => row.id === id); const other = index + direction; if (index < 0 || other < 0 || other >= ordered.length) return rows; const current = ordered[index]; const target = ordered[other]; return rows.map((row) => row.id === current.id ? { ...row, order: target.order } : row.id === target.id ? { ...row, order: current.order } : row); }

  return <main className={styles.shell}>
    <header className={styles.header}><div><div className={styles.eyebrow}>AA Mining · расширенное администрирование</div><h1>Конструктор системы</h1><p>Структура сайта, формы, таблицы, согласования, документы, уведомления и права.</p></div><div className={styles.headerActions}><a href="/">Вернуться на сайт</a><button onClick={exportData}>Резервная копия</button></div></header>
    <div className={styles.body}>
      <aside className={styles.sidebar}>{[
        ["overview","Обзор"],["structure","Структура сайта"],["forms","Формы и поля"],["tables","Таблицы и фильтры"],["workflows","Согласования"],["statuses","Статусы"],["documents","Документы"],["notifications","Уведомления"],["numbering","Нумерация"],["roles","Роли и права"],["history","История"],["backup","Резервные копии"],
      ].map(([id,label]) => <button key={id} className={mode === id ? styles.activeNav : ""} onClick={() => setMode(id as Mode)}>{label}</button>)}</aside>
      <section className={styles.content}>{notice ? <div className={styles.notice}>{notice}</div> : null}
        {mode === "overview" && <Overview data={data} setMode={setMode} />}
        {mode === "structure" && <Structure data={data} selectedTab={selectedTab} setSelectedTab={setSelectedTab} open={setModal} move={move} updateBuilder={updateBuilder} />}
        {mode === "forms" && <Forms data={data} selectedTab={selectedTab} selectedSection={selectedSection} setSelectedTab={setSelectedTab} setSelectedSection={setSelectedSection} sectionsForTab={sectionsForTab} fieldsForSection={fieldsForSection} open={setModal} move={move} updateBuilder={updateBuilder} />}
        {mode === "tables" && <Tables data={data} selectedSection={selectedSection} setSelectedSection={setSelectedSection} open={setModal} />}
        {mode === "workflows" && <Workflows rows={advanced.workflows} roles={builder.roles || []} open={setModal} update={(rows, action, id, details) => updateBuilder({ ...builder, advanced: { ...advanced, workflows: rows } }, action, "Согласование", id, details)} />}
        {mode === "statuses" && <Statuses rows={advanced.statuses} open={setModal} update={(rows, action, id, details) => updateBuilder({ ...builder, advanced: { ...advanced, statuses: rows } }, action, "Статус", id, details)} />}
        {mode === "documents" && <Documents rows={advanced.documents} open={setModal} update={(rows, action, id, details) => updateBuilder({ ...builder, advanced: { ...advanced, documents: rows } }, action, "Правило документа", id, details)} />}
        {mode === "notifications" && <Notifications rows={advanced.notifications} open={setModal} update={(rows, action, id, details) => updateBuilder({ ...builder, advanced: { ...advanced, notifications: rows } }, action, "Уведомление", id, details)} />}
        {mode === "numbering" && <Numbering rows={advanced.numbering} open={setModal} update={(rows, action, id, details) => updateBuilder({ ...builder, advanced: { ...advanced, numbering: rows } }, action, "Нумерация", id, details)} />}
        {mode === "roles" && <Roles roles={builder.roles || []} open={setModal} update={(roles, action, id, details) => updateBuilder({ ...builder, roles }, action, "Роль", id, details)} />}
        {mode === "history" && <History rows={data.audit || []} />}
        {mode === "backup" && <Backup exportData={exportData} importData={importData} reset={() => confirm("Сбросить только расширенные настройки к исходным?") && updateBuilder({ ...builder, advanced: defaultAdvanced }, "Сброс", "Расширенные настройки", "advanced", "Восстановлены исходные настройки")} />}
      </section>
    </div>
    {modal.kind ? <EditorModal modal={modal} close={() => setModal({ kind: null })} data={data} selectedTab={selectedTabRow} selectedSection={selectedSectionRow} persistBuilder={updateBuilder} notice={setNotice} /> : null}
  </main>;
}

function Overview({ data, setMode }: { data: StoredData; setMode: (mode: Mode) => void }) {
  const builder = data.builder!; const advanced = builder.advanced!;
  const cards = [
    ["Вкладки", builder.tabs?.filter((x) => !x.archived).length || 0, "structure"],
    ["Разделы", builder.sections?.filter((x) => !x.archived).length || 0, "forms"],
    ["Поля", builder.fields?.filter((x) => !x.archived).length || 0, "forms"],
    ["Маршруты согласования", advanced.workflows.length, "workflows"],
    ["Роли", builder.roles?.length || 0, "roles"],
    ["Правила документов", advanced.documents.length, "documents"],
  ];
  return <><PageHead title="Обзор конструктора" text="Здесь настраивается не только внешний вид, но и логика работы системы." /><div className={styles.metrics}>{cards.map(([label,value,mode]) => <button key={String(label)} onClick={() => setMode(mode as Mode)}><span>{label}</span><strong>{value}</strong></button>)}</div><div className={styles.grid2}><Panel title="Что можно настроить"><ul className={styles.featureList}><li>Вкладки, разделы и порядок отображения</li><li>Поля форм, обязательность и проверки</li><li>Колонки, поиск, фильтры и массовые действия</li><li>Этапы согласования и полномочия согласующих</li><li>Статусы и возможность редактирования</li><li>Автоматическое формирование PDF</li><li>Уведомления по событиям</li><li>Нумерацию документов</li><li>Роли и разрешения понятными галочками</li></ul></Panel><Panel title="Состояние"><Status label="Активные статусы" value={String(advanced.statuses.filter((x) => x.active).length)} /><Status label="Активные уведомления" value={String(advanced.notifications.filter((x) => x.active).length)} /><Status label="Правила нумерации" value={String(advanced.numbering.filter((x) => x.active).length)} /><Status label="Записей в журнале" value={String(data.audit?.length || 0)} /></Panel></div></>;
}

function Structure({ data, selectedTab, setSelectedTab, open, move, updateBuilder }: { data: StoredData; selectedTab: string; setSelectedTab: (id: string) => void; open: (modal: ModalState) => void; move: <T extends { id: string; order: number }>(rows: T[], id: string, direction: -1 | 1) => T[]; updateBuilder: (builder: StoredData["builder"], action: string, entity: string, id: string, details: string) => void }) {
  const builder = data.builder!; const tabs = sorted(builder.tabs || []); const sections = sorted((builder.sections || []).filter((x) => x.tabId === selectedTab));
  return <><PageHead title="Структура сайта" text="Вкладки можно создавать, переименовывать, скрывать, архивировать, дублировать и менять местами." action="Добавить вкладку" onAction={() => open({ kind: "tab" })} /><div className={styles.builder}><div className={styles.listPanel}><h3>Вкладки</h3>{tabs.map((tab) => <div key={tab.id} className={`${styles.rowCard} ${selectedTab === tab.id ? styles.selected : ""} ${tab.archived ? styles.archived : ""}`}><button className={styles.selectButton} onClick={() => setSelectedTab(tab.id)}><strong>{tab.label}</strong><small>{tab.systemTarget ? "Системная вкладка" : "Пользовательская вкладка"} · {tab.visible ? "видна" : "скрыта"}</small></button><Actions><button onClick={() => open({ kind: "tab", id: tab.id })}>Изменить</button><button onClick={() => updateBuilder({ ...builder, tabs: move(builder.tabs || [], tab.id, -1) }, "Перемещение", "Вкладка", tab.id, "Перемещена выше")}>↑</button><button onClick={() => updateBuilder({ ...builder, tabs: move(builder.tabs || [], tab.id, 1) }, "Перемещение", "Вкладка", tab.id, "Перемещена ниже")}>↓</button><button onClick={() => { const copy = { ...tab, id: uid("tab"), label: `${tab.label} — копия`, systemTarget: undefined, order: (builder.tabs || []).length }; updateBuilder({ ...builder, tabs: [...(builder.tabs || []), copy] }, "Дублирование", "Вкладка", copy.id, copy.label); }}>Копия</button><button className={styles.danger} onClick={() => updateBuilder({ ...builder, tabs: (builder.tabs || []).map((x) => x.id === tab.id ? { ...x, archived: !x.archived, visible: x.archived } : x) }, tab.archived ? "Восстановление" : "Архивирование", "Вкладка", tab.id, tab.archived ? "Вкладка восстановлена" : "Вкладка отправлена в архив")}>{tab.archived ? "Восстановить" : "В архив"}</button></Actions></div>)}</div><div className={styles.canvas}><div className={styles.canvasHead}><div><h3>{tabs.find((x) => x.id === selectedTab)?.label || "Выберите вкладку"}</h3><p>Разделы внутри выбранной вкладки</p></div><button className={styles.primary} disabled={!selectedTab} onClick={() => open({ kind: "section", parentId: selectedTab })}>Добавить раздел</button></div>{sections.length === 0 ? <Empty text="Разделы ещё не добавлены." /> : <div className={styles.cardGrid}>{sections.map((section) => <div key={section.id} className={`${styles.sectionCard} ${section.archived ? styles.archived : ""}`}><strong>{section.title}</strong><p>{section.description || "Без описания"}</p><small>{section.type === "table" ? "Таблица" : section.type === "form" ? "Форма" : "Информационный блок"} · {section.visible ? "виден" : "скрыт"}</small><Actions><button onClick={() => open({ kind: "section", id: section.id, parentId: selectedTab })}>Изменить</button><button className={styles.danger} onClick={() => updateBuilder({ ...builder, sections: (builder.sections || []).map((x) => x.id === section.id ? { ...x, archived: !x.archived, visible: x.archived } : x) }, section.archived ? "Восстановление" : "Архивирование", "Раздел", section.id, section.title)}>{section.archived ? "Восстановить" : "В архив"}</button></Actions></div>)}</div>}</div></div></>;
}

function Forms({ data, selectedTab, selectedSection, setSelectedTab, setSelectedSection, sectionsForTab, fieldsForSection, open, move, updateBuilder }: { data: StoredData; selectedTab: string; selectedSection: string; setSelectedTab: (id: string) => void; setSelectedSection: (id: string) => void; sectionsForTab: BuilderSection[]; fieldsForSection: BuilderField[]; open: (modal: ModalState) => void; move: <T extends { id: string; order: number }>(rows: T[], id: string, direction: -1 | 1) => T[]; updateBuilder: (builder: StoredData["builder"], action: string, entity: string, id: string, details: string) => void }) {
  const builder = data.builder!;
  return <><PageHead title="Формы и поля" text="Настройка подписей, типов, обязательности, подсказок, проверок, таблицы, поиска и фильтров." action="Добавить поле" onAction={() => selectedSection ? open({ kind: "field", parentId: selectedSection }) : alert("Сначала выберите раздел")} /><div className={styles.selectionBar}><label>Вкладка<select value={selectedTab} onChange={(e) => { setSelectedTab(e.target.value); setSelectedSection(""); }}><option value="">Выберите вкладку</option>{sorted(builder.tabs || []).filter((x) => !x.archived).map((x) => <option key={x.id} value={x.id}>{x.label}</option>)}</select></label><label>Раздел<select value={selectedSection} onChange={(e) => setSelectedSection(e.target.value)}><option value="">Выберите раздел</option>{sectionsForTab.filter((x) => !x.archived).map((x) => <option key={x.id} value={x.id}>{x.title}</option>)}</select></label></div>{!selectedSection ? <Empty text="Выберите вкладку и раздел." /> : <div className={styles.grid2}><Panel title="Поля формы">{fieldsForSection.length === 0 ? <Empty text="Поля не добавлены." /> : fieldsForSection.map((field) => <div key={field.id} className={`${styles.rowCard} ${field.archived ? styles.archived : ""}`}><div><strong>{field.label}</strong><small>{field.type} · ключ: {field.key} · {field.required ? "обязательное" : "необязательное"} · {field.showInTable === false ? "не показывать в таблице" : "колонка таблицы"}</small></div><Actions><button onClick={() => open({ kind: "field", id: field.id, parentId: selectedSection })}>Настроить</button><button onClick={() => updateBuilder({ ...builder, fields: move(builder.fields || [], field.id, -1) }, "Перемещение", "Поле", field.id, "Перемещено выше")}>↑</button><button onClick={() => updateBuilder({ ...builder, fields: move(builder.fields || [], field.id, 1) }, "Перемещение", "Поле", field.id, "Перемещено ниже")}>↓</button><button onClick={() => { const copy = { ...field, id: uid("field"), key: `${field.key}_copy`, label: `${field.label} — копия`, order: (builder.fields || []).filter((x) => x.sectionId === selectedSection).length }; updateBuilder({ ...builder, fields: [...(builder.fields || []), copy] }, "Дублирование", "Поле", copy.id, copy.label); }}>Копия</button><button className={styles.danger} onClick={() => updateBuilder({ ...builder, fields: (builder.fields || []).map((x) => x.id === field.id ? { ...x, archived: !x.archived, visible: x.archived } : x) }, field.archived ? "Восстановление" : "Архивирование", "Поле", field.id, field.label)}>{field.archived ? "Восстановить" : "В архив"}</button></Actions></div>)}</Panel><Panel title="Предварительный вид"><div className={styles.previewForm}>{fieldsForSection.filter((x) => x.visible && !x.archived).map((field) => <label key={field.id}><span>{field.label}{field.required ? " *" : ""}</span>{field.type === "textarea" ? <textarea placeholder={field.placeholder} disabled={field.readOnly} /> : field.type === "select" ? <select disabled={field.readOnly}><option>{field.placeholder || "Выберите"}</option>{field.options.map((x) => <option key={x}>{x}</option>)}</select> : field.type === "checkbox" ? <input type="checkbox" disabled={field.readOnly} /> : <input type={field.type === "datetime" ? "datetime-local" : field.type} placeholder={field.placeholder} disabled={field.readOnly} />}{field.helpText ? <small>{field.helpText}</small> : null}</label>)}</div></Panel></div>}</>;
}

function Tables({ data, selectedSection, setSelectedSection, open }: { data: StoredData; selectedSection: string; setSelectedSection: (id: string) => void; open: (modal: ModalState) => void }) {
  const builder = data.builder!; const config = builder.advanced!.tables.find((x) => x.sectionId === selectedSection);
  return <><PageHead title="Таблицы и фильтры" text="Отдельные параметры отображения для каждой таблицы." action="Настроить таблицу" onAction={() => selectedSection ? open({ kind: "table", id: config?.id, parentId: selectedSection }) : alert("Выберите раздел")} /><div className={styles.selectionBar}><label>Раздел<select value={selectedSection} onChange={(e) => setSelectedSection(e.target.value)}><option value="">Выберите раздел</option>{sorted(builder.sections || []).filter((x) => !x.archived).map((x) => <option key={x.id} value={x.id}>{x.title}</option>)}</select></label></div>{!selectedSection ? <Empty text="Выберите раздел, для которого нужно настроить таблицу." /> : <div className={styles.grid2}><Panel title="Параметры"><Status label="Постраничный вывод" value={config?.pagination !== false ? "Включён" : "Выключен"} /><Status label="Строк на странице" value={String(config?.pageSize || 25)} /><Status label="Поиск" value={config?.search !== false ? "Включён" : "Выключен"} /><Status label="Фильтры" value={config?.filters !== false ? "Включены" : "Выключены"} /><Status label="Массовые действия" value={config?.bulkActions ? "Включены" : "Выключены"} /></Panel><Panel title="Экспорт и оформление"><Status label="Excel" value={config?.exportExcel !== false ? "Доступен" : "Отключён"} /><Status label="PDF" value={config?.exportPdf ? "Доступен" : "Отключён"} /><Status label="Номера строк" value={config?.rowNumbers ? "Показываются" : "Скрыты"} /><Status label="Закреплённая шапка" value={config?.stickyHeader !== false ? "Да" : "Нет"} /><Status label="Компактный режим" value={config?.compact ? "Да" : "Нет"} /></Panel></div>}</>;
}

function Workflows({ rows, roles, open, update }: { rows: Workflow[]; roles: BuilderRole[]; open: (modal: ModalState) => void; update: (rows: Workflow[], action: string, id: string, details: string) => void }) {
  return <><PageHead title="Маршруты согласования" text="Настраивайте этапы, роли, сроки, право возврата и редактирования." action="Добавить маршрут" onAction={() => open({ kind: "workflow" })} />{rows.map((row) => <div key={row.id} className={styles.workflowCard}><div className={styles.workflowHead}><div><h3>{row.name}</h3><p>{row.entity} · {row.active ? "активен" : "отключён"} · PDF после завершения: {row.autoGeneratePdf ? "да" : "нет"}</p></div><Actions><button onClick={() => open({ kind: "workflow", id: row.id })}>Изменить</button><button onClick={() => update(rows.map((x) => x.id === row.id ? { ...x, active: !x.active } : x), "Изменение статуса", row.id, row.active ? "Маршрут отключён" : "Маршрут включён")}>{row.active ? "Отключить" : "Включить"}</button><button className={styles.danger} onClick={() => confirm("Удалить маршрут согласования?") && update(rows.filter((x) => x.id !== row.id), "Удаление", row.id, row.name)}>Удалить</button></Actions></div><div className={styles.stageLine}>{row.stages.map((stage, index) => <div key={stage.id}><b>{index + 1}</b><strong>{stage.name}</strong><small>Роль: {stage.role || roles[0]?.name || "не назначена"}</small><small>{stage.required ? "Обязательный" : "Необязательный"} · срок {stage.deadlineHours || 0} ч</small><small>{stage.canReturn ? "может вернуть" : "без возврата"} · {stage.canEdit ? "может изменить" : "только решение"}</small></div>)}</div></div>)}</>;
}
function Statuses({ rows, open, update }: { rows: StatusConfig[]; open: (modal: ModalState) => void; update: (rows: StatusConfig[], action: string, id: string, details: string) => void }) { return <><PageHead title="Статусы" text="Статусы процессов, порядок, финальность и разрешение редактирования." action="Добавить статус" onAction={() => open({ kind: "status" })} /><Table headers={["Процесс", "Статус", "Код", "Редактирование", "Финальный", "Статус", "Действия"]}>{sorted(rows).map((row) => <tr key={row.id}><td>{row.entity}</td><td><strong>{row.name}</strong></td><td>{row.code}</td><td>{row.allowEdit ? "Разрешено" : "Запрещено"}</td><td>{row.final ? "Да" : "Нет"}</td><td>{row.active ? "Активен" : "Отключён"}</td><td><Actions><button onClick={() => open({ kind: "status", id: row.id })}>Изменить</button><button onClick={() => update(rows.map((x) => x.id === row.id ? { ...x, active: !x.active } : x), "Изменение статуса", row.id, row.name)}>{row.active ? "Отключить" : "Включить"}</button><button className={styles.danger} onClick={() => confirm("Удалить статус?") && update(rows.filter((x) => x.id !== row.id), "Удаление", row.id, row.name)}>Удалить</button></Actions></td></tr>)}</Table></>; }
function Documents({ rows, open, update }: { rows: DocumentRule[]; open: (modal: ModalState) => void; update: (rows: DocumentRule[], action: string, id: string, details: string) => void }) { return <><PageHead title="Автоматизация документов" text="Привязка шаблона, события, формата и объединения в один пакет." action="Добавить правило" onAction={() => open({ kind: "document" })} /><Table headers={["Название", "Процесс", "Событие", "Шаблон", "Формат", "Единый пакет", "Действия"]}>{rows.map((row) => <tr key={row.id}><td><strong>{row.name}</strong><small>{row.active ? "Активно" : "Отключено"}</small></td><td>{row.entity}</td><td>{row.trigger}</td><td>{row.templateName}</td><td>{row.output}</td><td>{row.mergePackage ? "Да" : "Нет"}</td><td><Actions><button onClick={() => open({ kind: "document", id: row.id })}>Изменить</button><button onClick={() => update(rows.map((x) => x.id === row.id ? { ...x, active: !x.active } : x), "Изменение статуса", row.id, row.name)}>{row.active ? "Отключить" : "Включить"}</button><button className={styles.danger} onClick={() => confirm("Удалить правило?") && update(rows.filter((x) => x.id !== row.id), "Удаление", row.id, row.name)}>Удалить</button></Actions></td></tr>)}</Table></>; }
function Notifications({ rows, open, update }: { rows: NotificationRule[]; open: (modal: ModalState) => void; update: (rows: NotificationRule[], action: string, id: string, details: string) => void }) { return <><PageHead title="Уведомления" text="Событие, канал, получатель и собственный текст уведомления." action="Добавить уведомление" onAction={() => open({ kind: "notification" })} /><Table headers={["Название", "Событие", "Канал", "Получатель", "Сообщение", "Статус", "Действия"]}>{rows.map((row) => <tr key={row.id}><td><strong>{row.name}</strong></td><td>{row.event}</td><td>{row.channel}</td><td>{row.recipient}</td><td>{row.message}</td><td>{row.active ? "Активно" : "Отключено"}</td><td><Actions><button onClick={() => open({ kind: "notification", id: row.id })}>Изменить</button><button onClick={() => update(rows.map((x) => x.id === row.id ? { ...x, active: !x.active } : x), "Изменение статуса", row.id, row.name)}>{row.active ? "Отключить" : "Включить"}</button><button className={styles.danger} onClick={() => confirm("Удалить уведомление?") && update(rows.filter((x) => x.id !== row.id), "Удаление", row.id, row.name)}>Удалить</button></Actions></td></tr>)}</Table></>; }
function Numbering({ rows, open, update }: { rows: NumberingRule[]; open: (modal: ModalState) => void; update: (rows: NumberingRule[], action: string, id: string, details: string) => void }) { return <><PageHead title="Нумерация" text="Префикс, количество цифр, следующий номер и период сброса." action="Добавить правило" onAction={() => open({ kind: "numbering" })} /><Table headers={["Объект", "Пример номера", "Следующий", "Сброс", "Статус", "Действия"]}>{rows.map((row) => <tr key={row.id}><td><strong>{row.entity}</strong></td><td>{row.prefix}{row.separator}{String(row.nextNumber).padStart(row.digits, "0")}</td><td>{row.nextNumber}</td><td>{row.reset}</td><td>{row.active ? "Активно" : "Отключено"}</td><td><Actions><button onClick={() => open({ kind: "numbering", id: row.id })}>Изменить</button><button onClick={() => update(rows.map((x) => x.id === row.id ? { ...x, active: !x.active } : x), "Изменение статуса", row.id, row.entity)}>{row.active ? "Отключить" : "Включить"}</button><button className={styles.danger} onClick={() => confirm("Удалить правило нумерации?") && update(rows.filter((x) => x.id !== row.id), "Удаление", row.id, row.entity)}>Удалить</button></Actions></td></tr>)}</Table></>; }
function Roles({ roles, open, update }: { roles: BuilderRole[]; open: (modal: ModalState) => void; update: (roles: BuilderRole[], action: string, id: string, details: string) => void }) { return <><PageHead title="Роли и разрешения" text="Каждое разрешение выбирается понятной галочкой с названием и описанием." action="Добавить роль" onAction={() => open({ kind: "role" })} /><div className={styles.roleGrid}>{roles.map((role) => <div key={role.id} className={styles.roleCard}><div><h3>{role.name}</h3><p>{role.active ? "Активная роль" : "Роль отключена"}</p></div><strong>{role.permissions.includes("admin.full") ? "Полный доступ" : `${role.permissions.length} разрешений`}</strong><div className={styles.permissionSummary}>{permissionGroups.flatMap((group) => group.items).filter((item) => role.permissions.includes(item.id)).slice(0, 8).map((item) => <span key={item.id}>{item.label}</span>)}{role.permissions.length > 8 ? <span>+ ещё {role.permissions.length - 8}</span> : null}</div><Actions><button onClick={() => open({ kind: "role", id: role.id })}>Настроить разрешения</button><button onClick={() => update(roles.map((x) => x.id === role.id ? { ...x, active: !x.active } : x), "Изменение статуса", role.id, role.name)}>{role.active ? "Отключить" : "Включить"}</button><button className={styles.danger} onClick={() => confirm("Удалить роль?") && update(roles.filter((x) => x.id !== role.id), "Удаление", role.id, role.name)}>Удалить</button></Actions></div>)}</div></>; }
function History({ rows }: { rows: AuditRow[] }) { return <><PageHead title="История изменений" text="Административные действия сохраняются с датой, объектом и описанием." />{rows.length === 0 ? <Empty text="История пока пуста." /> : <Table headers={["Дата", "Пользователь", "Действие", "Объект", "Описание"]}>{rows.map((row) => <tr key={row.id}><td>{row.at}</td><td>{row.actor}</td><td>{row.action}</td><td>{row.entity}<small>{row.entityId}</small></td><td>{row.details}</td></tr>)}</Table>}</>; }
function Backup({ exportData, importData, reset }: { exportData: () => void; importData: (file: File) => void; reset: () => void }) { return <><PageHead title="Резервные копии" text="Сохраняется полная конфигурация, роли, разрешения, данные и история." /><div className={styles.grid2}><Panel title="Экспорт"><p>Скачайте один JSON-файл со всей конфигурацией.</p><button className={styles.primary} onClick={exportData}>Скачать резервную копию</button></Panel><Panel title="Импорт"><p>Загрузка заменит текущую конфигурацию данными из файла.</p><label className={styles.fileButton}>Выбрать JSON<input type="file" accept="application/json" onChange={(event) => event.target.files?.[0] && importData(event.target.files[0])} /></label></Panel></div><Panel title="Сброс расширенных настроек"><p>Структура, пользователи и заявки сохранятся. Будут восстановлены только исходные маршруты согласования, статусы, документы, уведомления и нумерация.</p><button className={styles.dangerLarge} onClick={reset}>Сбросить расширенные настройки</button></Panel></>; }

function EditorModal({ modal, close, data, selectedTab, selectedSection, persistBuilder, notice }: { modal: ModalState; close: () => void; data: StoredData; selectedTab?: BuilderTab; selectedSection?: BuilderSection; persistBuilder: (builder: StoredData["builder"], action: string, entity: string, id: string, details: string) => void; notice: (message: string) => void }) {
  const builder = data.builder!; const advanced = builder.advanced!;
  const tab = builder.tabs?.find((x) => x.id === modal.id); const section = builder.sections?.find((x) => x.id === modal.id); const field = builder.fields?.find((x) => x.id === modal.id); const table = advanced.tables.find((x) => x.id === modal.id); const workflow = advanced.workflows.find((x) => x.id === modal.id); const status = advanced.statuses.find((x) => x.id === modal.id); const document = advanced.documents.find((x) => x.id === modal.id); const notification = advanced.notifications.find((x) => x.id === modal.id); const numbering = advanced.numbering.find((x) => x.id === modal.id); const role = builder.roles?.find((x) => x.id === modal.id);
  const [stageCount, setStageCount] = useState(workflow?.stages.length || 1);
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget);
    if (modal.kind === "tab") { const row: BuilderTab = { id: tab?.id || uid("tab"), label: s(form.get("label")), systemTarget: s(form.get("systemTarget")) || undefined, visible: form.get("visible") === "on", archived: form.get("archived") === "on", order: tab?.order ?? (builder.tabs?.length || 0) }; persistBuilder({ ...builder, tabs: tab ? builder.tabs?.map((x) => x.id === row.id ? row : x) : [...(builder.tabs || []), row] }, tab ? "Редактирование" : "Создание", "Вкладка", row.id, row.label); }
    if (modal.kind === "section") { const row: BuilderSection = { id: section?.id || uid("section"), tabId: modal.parentId || section?.tabId || selectedTab?.id || "", title: s(form.get("title")), description: s(form.get("description")), type: s(form.get("type")) as BuilderSection["type"], visible: form.get("visible") === "on", archived: form.get("archived") === "on", order: section?.order ?? (builder.sections?.filter((x) => x.tabId === (modal.parentId || selectedTab?.id)).length || 0) }; persistBuilder({ ...builder, sections: section ? builder.sections?.map((x) => x.id === row.id ? row : x) : [...(builder.sections || []), row] }, section ? "Редактирование" : "Создание", "Раздел", row.id, row.title); }
    if (modal.kind === "field") { const row: BuilderField = { id: field?.id || uid("field"), sectionId: modal.parentId || field?.sectionId || selectedSection?.id || "", label: s(form.get("label")), key: s(form.get("key")) || uid("value"), type: s(form.get("type")) as BuilderField["type"], required: form.get("required") === "on", visible: form.get("visible") === "on", archived: form.get("archived") === "on", order: field?.order ?? (builder.fields?.filter((x) => x.sectionId === (modal.parentId || selectedSection?.id)).length || 0), options: s(form.get("options")).split(",").map((x) => x.trim()).filter(Boolean), placeholder: s(form.get("placeholder")), helpText: s(form.get("helpText")), defaultValue: s(form.get("defaultValue")), readOnly: form.get("readOnly") === "on", unique: form.get("unique") === "on", showInTable: form.get("showInTable") === "on", searchable: form.get("searchable") === "on", filterable: form.get("filterable") === "on", sortable: form.get("sortable") === "on", min: s(form.get("min")) ? n(form.get("min")) : null, max: s(form.get("max")) ? n(form.get("max")) : null, validationPattern: s(form.get("validationPattern")), visibilityRule: s(form.get("visibilityRule")) }; persistBuilder({ ...builder, fields: field ? builder.fields?.map((x) => x.id === row.id ? row : x) : [...(builder.fields || []), row] }, field ? "Редактирование" : "Создание", "Поле", row.id, row.label); }
    if (modal.kind === "table") { const row: TableConfig = { id: table?.id || uid("table"), sectionId: modal.parentId || table?.sectionId || selectedSection?.id || "", pagination: form.get("pagination") === "on", pageSize: n(form.get("pageSize")) || 25, search: form.get("search") === "on", filters: form.get("filters") === "on", exportExcel: form.get("exportExcel") === "on", exportPdf: form.get("exportPdf") === "on", rowNumbers: form.get("rowNumbers") === "on", bulkActions: form.get("bulkActions") === "on", stickyHeader: form.get("stickyHeader") === "on", compact: form.get("compact") === "on" }; persistBuilder({ ...builder, advanced: { ...advanced, tables: table ? advanced.tables.map((x) => x.id === row.id ? row : x) : [...advanced.tables, row] } }, table ? "Редактирование" : "Создание", "Таблица", row.id, row.sectionId); }
    if (modal.kind === "workflow") { const stages: WorkflowStage[] = Array.from({ length: stageCount }, (_, index) => ({ id: workflow?.stages[index]?.id || uid("stage"), name: s(form.get(`stageName-${index}`)) || `Этап ${index + 1}`, role: s(form.get(`stageRole-${index}`)), required: form.get(`stageRequired-${index}`) === "on", canReturn: form.get(`stageReturn-${index}`) === "on", canEdit: form.get(`stageEdit-${index}`) === "on", deadlineHours: n(form.get(`stageDeadline-${index}`)) })); const row: Workflow = { id: workflow?.id || uid("workflow"), name: s(form.get("name")), entity: s(form.get("entity")), active: form.get("active") === "on", autoGeneratePdf: form.get("autoGeneratePdf") === "on", stages }; persistBuilder({ ...builder, advanced: { ...advanced, workflows: workflow ? advanced.workflows.map((x) => x.id === row.id ? row : x) : [...advanced.workflows, row] } }, workflow ? "Редактирование" : "Создание", "Согласование", row.id, row.name); }
    if (modal.kind === "status") { const row: StatusConfig = { id: status?.id || uid("status"), entity: s(form.get("entity")), name: s(form.get("name")), code: s(form.get("code")), active: form.get("active") === "on", final: form.get("final") === "on", allowEdit: form.get("allowEdit") === "on", order: status?.order ?? advanced.statuses.length }; persistBuilder({ ...builder, advanced: { ...advanced, statuses: status ? advanced.statuses.map((x) => x.id === row.id ? row : x) : [...advanced.statuses, row] } }, status ? "Редактирование" : "Создание", "Статус", row.id, row.name); }
    if (modal.kind === "document") { const row: DocumentRule = { id: document?.id || uid("document"), name: s(form.get("name")), entity: s(form.get("entity")), trigger: s(form.get("trigger")), templateName: s(form.get("templateName")), output: s(form.get("output")) as DocumentRule["output"], mergePackage: form.get("mergePackage") === "on", active: form.get("active") === "on" }; persistBuilder({ ...builder, advanced: { ...advanced, documents: document ? advanced.documents.map((x) => x.id === row.id ? row : x) : [...advanced.documents, row] } }, document ? "Редактирование" : "Создание", "Правило документа", row.id, row.name); }
    if (modal.kind === "notification") { const row: NotificationRule = { id: notification?.id || uid("notification"), name: s(form.get("name")), event: s(form.get("event")), channel: s(form.get("channel")) as NotificationRule["channel"], recipient: s(form.get("recipient")), message: s(form.get("message")), active: form.get("active") === "on" }; persistBuilder({ ...builder, advanced: { ...advanced, notifications: notification ? advanced.notifications.map((x) => x.id === row.id ? row : x) : [...advanced.notifications, row] } }, notification ? "Редактирование" : "Создание", "Уведомление", row.id, row.name); }
    if (modal.kind === "numbering") { const row: NumberingRule = { id: numbering?.id || uid("numbering"), entity: s(form.get("entity")), prefix: s(form.get("prefix")), nextNumber: n(form.get("nextNumber")) || 1, digits: n(form.get("digits")) || 4, reset: s(form.get("reset")) as NumberingRule["reset"], separator: s(form.get("separator")), active: form.get("active") === "on" }; persistBuilder({ ...builder, advanced: { ...advanced, numbering: numbering ? advanced.numbering.map((x) => x.id === row.id ? row : x) : [...advanced.numbering, row] } }, numbering ? "Редактирование" : "Создание", "Нумерация", row.id, row.entity); }
    if (modal.kind === "role") { const permissions = form.getAll("permission").map(String); const row: BuilderRole = { id: role?.id || uid("role"), name: s(form.get("name")), active: form.get("active") === "on", permissions }; persistBuilder({ ...builder, roles: role ? builder.roles?.map((x) => x.id === row.id ? row : x) : [...(builder.roles || []), row] }, role ? "Редактирование" : "Создание", "Роль", row.id, `${row.name}: ${permissions.length} разрешений`); }
    notice("Изменения сохранены"); close();
  }
  return <Modal title={modal.id ? "Редактирование" : "Добавление"} close={close}><form className={styles.form} onSubmit={submit}>
    {modal.kind === "tab" && <><Field label="Название вкладки"><input name="label" required defaultValue={tab?.label} /></Field><Field label="Системный экран"><select name="systemTarget" defaultValue={tab?.systemTarget || ""}><option value="">Пользовательская вкладка</option><option value="dashboard">Главная</option><option value="requests">Заявки</option><option value="approval">Согласование</option><option value="routes">Маршруты</option><option value="documents">Документы</option><option value="reports">Месячный отчёт</option><option value="directories">Справочники</option><option value="admin">Администрирование</option></select></Field><Checks><label><input type="checkbox" name="visible" defaultChecked={tab?.visible ?? true} />Показывать в меню</label><label><input type="checkbox" name="archived" defaultChecked={tab?.archived} />Архив</label></Checks></>}
    {modal.kind === "section" && <><Field label="Название раздела"><input name="title" required defaultValue={section?.title} /></Field><Field label="Описание"><textarea name="description" defaultValue={section?.description} /></Field><Field label="Тип"><select name="type" defaultValue={section?.type || "table"}><option value="table">Таблица</option><option value="form">Форма</option><option value="dashboard">Информационный блок</option></select></Field><Checks><label><input type="checkbox" name="visible" defaultChecked={section?.visible ?? true} />Показывать</label><label><input type="checkbox" name="archived" defaultChecked={section?.archived} />Архив</label></Checks></>}
    {modal.kind === "field" && <><div className={styles.formGrid}><Field label="Название поля"><input name="label" required defaultValue={field?.label} /></Field><Field label="Системный ключ"><input name="key" required defaultValue={field?.key} placeholder="destination" /></Field></div><div className={styles.formGrid}><Field label="Тип поля"><select name="type" defaultValue={field?.type || "text"}><option value="text">Текст</option><option value="number">Число</option><option value="date">Дата</option><option value="datetime">Дата и время</option><option value="textarea">Большой текст</option><option value="select">Список</option><option value="checkbox">Галочка</option></select></Field><Field label="Значение по умолчанию"><input name="defaultValue" defaultValue={field?.defaultValue} /></Field></div><Field label="Подсказка внутри поля"><input name="placeholder" defaultValue={field?.placeholder} /></Field><Field label="Описание под полем"><input name="helpText" defaultValue={field?.helpText} /></Field><Field label="Варианты списка через запятую"><input name="options" defaultValue={field?.options?.join(", ")} /></Field><div className={styles.formGrid}><Field label="Минимальное значение"><input type="number" step="any" name="min" defaultValue={field?.min ?? ""} /></Field><Field label="Максимальное значение"><input type="number" step="any" name="max" defaultValue={field?.max ?? ""} /></Field></div><Field label="Шаблон проверки"><input name="validationPattern" defaultValue={field?.validationPattern} placeholder="Регулярное выражение или правило" /></Field><Field label="Условие видимости"><input name="visibilityRule" defaultValue={field?.visibilityRule} placeholder="Например: tripType = overnight" /></Field><div className={styles.checkGrid}><label><input type="checkbox" name="required" defaultChecked={field?.required} /><span><b>Обязательное</b><small>Без значения форму нельзя сохранить</small></span></label><label><input type="checkbox" name="readOnly" defaultChecked={field?.readOnly} /><span><b>Только чтение</b><small>Пользователь не сможет изменить значение</small></span></label><label><input type="checkbox" name="unique" defaultChecked={field?.unique} /><span><b>Уникальное значение</b><small>Запрет повторяющихся значений</small></span></label><label><input type="checkbox" name="visible" defaultChecked={field?.visible ?? true} /><span><b>Показывать в форме</b><small>Поле отображается пользователю</small></span></label><label><input type="checkbox" name="showInTable" defaultChecked={field?.showInTable ?? true} /><span><b>Показывать в таблице</b><small>Создать колонку в списке</small></span></label><label><input type="checkbox" name="searchable" defaultChecked={field?.searchable} /><span><b>Включить в поиск</b><small>Поиск будет учитывать это поле</small></span></label><label><input type="checkbox" name="filterable" defaultChecked={field?.filterable} /><span><b>Добавить фильтр</b><small>Поле появится среди фильтров</small></span></label><label><input type="checkbox" name="sortable" defaultChecked={field?.sortable} /><span><b>Разрешить сортировку</b><small>Сортировка по колонке</small></span></label><label><input type="checkbox" name="archived" defaultChecked={field?.archived} /><span><b>Архив</b><small>Скрыть поле, сохранив прежние данные</small></span></label></div></>}
    {modal.kind === "table" && <><Field label="Количество строк на странице"><input type="number" min="5" max="500" name="pageSize" defaultValue={table?.pageSize || 25} /></Field><div className={styles.checkGrid}><CheckCard name="pagination" label="Постраничный вывод" text="Делить длинный список на страницы" checked={table?.pagination ?? true} /><CheckCard name="search" label="Строка поиска" text="Показывать поиск над таблицей" checked={table?.search ?? true} /><CheckCard name="filters" label="Панель фильтров" text="Показывать фильтры по полям" checked={table?.filters ?? true} /><CheckCard name="exportExcel" label="Экспорт в Excel" text="Разрешить выгрузку таблицы" checked={table?.exportExcel ?? true} /><CheckCard name="exportPdf" label="Экспорт в PDF" text="Разрешить печатную выгрузку" checked={table?.exportPdf ?? false} /><CheckCard name="rowNumbers" label="Номера строк" text="Показывать порядковый номер" checked={table?.rowNumbers ?? false} /><CheckCard name="bulkActions" label="Массовые действия" text="Выбор нескольких строк галочками" checked={table?.bulkActions ?? false} /><CheckCard name="stickyHeader" label="Закрепить шапку" text="Заголовки остаются при прокрутке" checked={table?.stickyHeader ?? true} /><CheckCard name="compact" label="Компактный режим" text="Уменьшенные отступы строк" checked={table?.compact ?? false} /></div></>}
    {modal.kind === "workflow" && <><Field label="Название маршрута"><input name="name" required defaultValue={workflow?.name} /></Field><Field label="Процесс / объект"><input name="entity" required defaultValue={workflow?.entity || "Заявка"} /></Field><Checks><label><input type="checkbox" name="active" defaultChecked={workflow?.active ?? true} />Активен</label><label><input type="checkbox" name="autoGeneratePdf" defaultChecked={workflow?.autoGeneratePdf ?? true} />После завершения сформировать PDF</label></Checks><div className={styles.stageEditorHead}><h3>Этапы согласования</h3><Actions><button type="button" onClick={() => setStageCount((value) => value + 1)}>Добавить этап</button><button type="button" disabled={stageCount <= 1} onClick={() => setStageCount((value) => Math.max(1, value - 1))}>Убрать последний</button></Actions></div>{Array.from({ length: stageCount }, (_, index) => { const stage = workflow?.stages[index]; return <div className={styles.stageEditor} key={index}><b>Этап {index + 1}</b><div className={styles.formGrid}><Field label="Название этапа"><input name={`stageName-${index}`} required defaultValue={stage?.name} /></Field><Field label="Роль согласующего"><select name={`stageRole-${index}`} defaultValue={stage?.role || ""}><option value="">Выберите роль</option>{builder.roles?.map((item) => <option key={item.id}>{item.name}</option>)}</select></Field></div><Field label="Срок согласования, часов"><input type="number" min="0" name={`stageDeadline-${index}`} defaultValue={stage?.deadlineHours || 24} /></Field><Checks><label><input type="checkbox" name={`stageRequired-${index}`} defaultChecked={stage?.required ?? true} />Обязательный этап</label><label><input type="checkbox" name={`stageReturn-${index}`} defaultChecked={stage?.canReturn ?? true} />Может вернуть автору</label><label><input type="checkbox" name={`stageEdit-${index}`} defaultChecked={stage?.canEdit} />Может редактировать заявку</label></Checks></div>; })}</>}
    {modal.kind === "status" && <><div className={styles.formGrid}><Field label="Процесс"><input name="entity" required defaultValue={status?.entity || "Заявка"} /></Field><Field label="Название статуса"><input name="name" required defaultValue={status?.name} /></Field></div><Field label="Системный код"><input name="code" required defaultValue={status?.code} /></Field><Checks><label><input type="checkbox" name="active" defaultChecked={status?.active ?? true} />Активен</label><label><input type="checkbox" name="allowEdit" defaultChecked={status?.allowEdit} />Разрешить редактирование</label><label><input type="checkbox" name="final" defaultChecked={status?.final} />Финальный статус</label></Checks></>}
    {modal.kind === "document" && <><Field label="Название правила"><input name="name" required defaultValue={document?.name} /></Field><div className={styles.formGrid}><Field label="Процесс"><input name="entity" required defaultValue={document?.entity || "Заявка"} /></Field><Field label="Событие"><select name="trigger" defaultValue={document?.trigger || "После окончательного согласования"}><option>После создания</option><option>После отправки на согласование</option><option>После окончательного согласования</option><option>После завершения поездки</option><option>Вручную</option></select></Field></div><Field label="Шаблон или комплект"><input name="templateName" required defaultValue={document?.templateName} /></Field><Field label="Формат результата"><select name="output" defaultValue={document?.output || "PDF"}><option>PDF</option><option>DOCX</option><option>PDF и DOCX</option></select></Field><Checks><label><input type="checkbox" name="mergePackage" defaultChecked={document?.mergePackage} />Объединить документы в один PDF</label><label><input type="checkbox" name="active" defaultChecked={document?.active ?? true} />Активно</label></Checks></>}
    {modal.kind === "notification" && <><Field label="Название"><input name="name" required defaultValue={notification?.name} /></Field><Field label="Событие"><input name="event" required defaultValue={notification?.event} /></Field><div className={styles.formGrid}><Field label="Канал"><select name="channel" defaultValue={notification?.channel || "В системе"}><option>В системе</option><option>Email</option><option>Telegram</option><option>В системе и Email</option></select></Field><Field label="Получатель"><input name="recipient" required defaultValue={notification?.recipient} /></Field></div><Field label="Текст сообщения"><textarea name="message" required defaultValue={notification?.message} /></Field><Checks><label><input type="checkbox" name="active" defaultChecked={notification?.active ?? true} />Активно</label></Checks></>}
    {modal.kind === "numbering" && <><Field label="Объект"><input name="entity" required defaultValue={numbering?.entity || "Заявка"} /></Field><div className={styles.formGrid}><Field label="Префикс"><input name="prefix" defaultValue={numbering?.prefix || "ЗГ"} /></Field><Field label="Разделитель"><input name="separator" defaultValue={numbering?.separator || "-"} /></Field></div><div className={styles.formGrid}><Field label="Следующий номер"><input type="number" min="1" name="nextNumber" defaultValue={numbering?.nextNumber || 1} /></Field><Field label="Количество цифр"><input type="number" min="1" max="10" name="digits" defaultValue={numbering?.digits || 4} /></Field></div><Field label="Сброс нумерации"><select name="reset" defaultValue={numbering?.reset || "Ежегодно"}><option>Никогда</option><option>Ежегодно</option><option>Ежемесячно</option></select></Field><Checks><label><input type="checkbox" name="active" defaultChecked={numbering?.active ?? true} />Активно</label></Checks></>}
    {modal.kind === "role" && <><Field label="Название роли"><input name="name" required defaultValue={role?.name} /></Field><Checks><label><input type="checkbox" name="active" defaultChecked={role?.active ?? true} />Роль активна</label></Checks><div className={styles.permissionToolbar}><span>Разрешения роли</span><Actions><button type="button" onClick={() => window.document.querySelectorAll<HTMLInputElement>('input[name="permission"]').forEach((input) => { input.checked = true; })}>Выбрать все</button><button type="button" onClick={() => window.document.querySelectorAll<HTMLInputElement>('input[name="permission"]').forEach((input) => { input.checked = false; })}>Снять все</button></Actions></div><div className={styles.permissionGroups}>{permissionGroups.map((group) => <fieldset key={group.title}><legend>{group.title}</legend><div className={styles.permissionGrid}>{group.items.map((permission) => <label key={permission.id} className={styles.permissionCard}><input type="checkbox" name="permission" value={permission.id} defaultChecked={role?.permissions.includes(permission.id)} /><span><b>{permission.label}</b><small>{permission.description}</small></span></label>)}</div></fieldset>)}</div></>}
    <div className={styles.modalActions}><button type="button" onClick={close}>Отмена</button><button className={styles.primary}>Сохранить</button></div>
  </form></Modal>;
}

function PageHead({ title, text, action, onAction }: { title: string; text: string; action?: string; onAction?: () => void }) { return <div className={styles.pageHead}><div><h2>{title}</h2><p>{text}</p></div>{action ? <button className={styles.primary} onClick={onAction}>{action}</button> : null}</div>; }
function Panel({ title, children }: { title: string; children: ReactNode }) { return <div className={styles.panel}><h2>{title}</h2>{children}</div>; }
function Status({ label, value }: { label: string; value: string }) { return <div className={styles.status}><span>{label}</span><strong>{value}</strong></div>; }
function Actions({ children }: { children: ReactNode }) { return <div className={styles.actions}>{children}</div>; }
function Empty({ text }: { text: string }) { return <div className={styles.empty}>{text}</div>; }
function Table({ headers, children }: { headers: string[]; children: ReactNode }) { return <div className={styles.tableWrap}><table><thead><tr>{headers.map((header) => <th key={header}>{header}</th>)}</tr></thead><tbody>{children}</tbody></table></div>; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className={styles.field}><span>{label}</span>{children}</label>; }
function Checks({ children }: { children: ReactNode }) { return <div className={styles.checks}>{children}</div>; }
function CheckCard({ name, label, text, checked }: { name: string; label: string; text: string; checked: boolean }) { return <label><input type="checkbox" name={name} defaultChecked={checked} /><span><b>{label}</b><small>{text}</small></span></label>; }
function Modal({ title, close, children }: { title: string; close: () => void; children: ReactNode }) { return <div className={styles.modalBackdrop} onMouseDown={(event) => event.target === event.currentTarget && close()}><div className={styles.modal}><div className={styles.modalHead}><h2>{title}</h2><button onClick={close}>×</button></div>{children}</div></div>; }
